-- READ-ONLY probe for 20261016140000_opps_v2_foundations.sql. Safe for MCP and prod.
-- Expected: palette + cover_url columns exist; world_club_crest_colors has RLS,
-- anon/authenticated read only, PUBLIC holds nothing; the three admin RPCs are
-- SECURITY DEFINER with search_path pinned, EXECUTE for authenticated only (anon
-- and PUBLIC revoked) and refuse non-admins inside.
SELECT CASE WHEN EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'club_crest_colors' AND column_name = 'palette') THEN 'PASS' ELSE 'FAIL' END AS status, 'club_crest_colors.palette exists' AS chk
UNION ALL SELECT CASE WHEN EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'opportunities' AND column_name = 'cover_url') THEN 'PASS' ELSE 'FAIL' END, 'opportunities.cover_url exists'
UNION ALL SELECT CASE WHEN to_regclass('public.world_club_crest_colors') IS NOT NULL THEN 'PASS' ELSE 'FAIL' END, 'world_club_crest_colors exists'
UNION ALL SELECT CASE WHEN (SELECT relrowsecurity FROM pg_class WHERE oid = 'public.world_club_crest_colors'::regclass) THEN 'PASS' ELSE 'FAIL' END, 'world table RLS enabled'
UNION ALL SELECT CASE WHEN has_table_privilege('anon', 'public.world_club_crest_colors', 'SELECT') AND has_table_privilege('authenticated', 'public.world_club_crest_colors', 'SELECT') THEN 'PASS' ELSE 'FAIL' END, 'world table readable'
UNION ALL SELECT CASE WHEN NOT has_table_privilege('anon', 'public.world_club_crest_colors', 'INSERT') AND NOT has_table_privilege('authenticated', 'public.world_club_crest_colors', 'INSERT') AND NOT has_table_privilege('authenticated', 'public.world_club_crest_colors', 'UPDATE') AND NOT has_table_privilege('authenticated', 'public.world_club_crest_colors', 'DELETE') THEN 'PASS' ELSE 'FAIL' END, 'world table: no client writes'
UNION ALL SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM aclexplode((SELECT relacl FROM pg_class WHERE oid = 'public.world_club_crest_colors'::regclass)) a WHERE a.grantee = 0) THEN 'PASS' ELSE 'FAIL' END, 'world table: PUBLIC holds nothing'
UNION ALL SELECT CASE WHEN (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('admin_crest_backfill_candidates', 'admin_set_crest_colors', 'admin_set_world_club_crest_colors') AND p.prosecdef AND array_to_string(p.proconfig, ',') LIKE '%search_path=public%') = 3 THEN 'PASS' ELSE 'FAIL' END, 'three admin RPCs: DEFINER + search_path pinned'
UNION ALL SELECT CASE WHEN NOT has_function_privilege('anon', 'public.admin_set_crest_colors(uuid, text, text, jsonb)', 'EXECUTE') AND NOT has_function_privilege('anon', 'public.admin_set_world_club_crest_colors(uuid, text, text, jsonb)', 'EXECUTE') AND NOT has_function_privilege('anon', 'public.admin_crest_backfill_candidates(integer)', 'EXECUTE') THEN 'PASS' ELSE 'FAIL' END, 'anon cannot execute admin RPCs'
UNION ALL SELECT CASE WHEN has_function_privilege('authenticated', 'public.admin_set_crest_colors(uuid, text, text, jsonb)', 'EXECUTE') THEN 'PASS' ELSE 'FAIL' END, 'authenticated can call (admin check inside)'
UNION ALL SELECT CASE WHEN (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('admin_crest_backfill_candidates', 'admin_set_crest_colors', 'admin_set_world_club_crest_colors') AND pg_get_functiondef(p.oid) LIKE '%is_platform_admin()%') = 3 THEN 'PASS' ELSE 'FAIL' END, 'admin RPCs check is_platform_admin()'
UNION ALL SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('admin_crest_backfill_candidates', 'admin_set_crest_colors', 'admin_set_world_club_crest_colors') AND EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0)) THEN 'PASS' ELSE 'FAIL' END, 'admin RPCs: PUBLIC holds nothing';
